<template>
  <NuxtLayout name="app">
    <div class="mx-auto max-w-6xl space-y-5 px-4 pt-4 sm:px-5 sm:pt-6">
      <header class="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        <div class="flex items-start gap-3"><NuxtLink class="btn btn-ghost btn-sm btn-square" to="/workspaces" :aria-label="t('workspaces.back')"><IconArrowLeft class="h-5 w-5" /></NuxtLink><div><div class="flex items-center gap-2"><div class="flex h-11 w-11 items-center justify-center overflow-hidden rounded-md bg-base-200 text-lg font-bold text-base-content/70"><img v-if="getFileUrl(workspace?.picture?.id)" :src="getFileUrl(workspace?.picture?.id)!" :alt="workspace?.name" class="h-full w-full object-cover" /><span v-else>{{ workspace?.name?.slice(0, 1).toUpperCase() }}</span></div><div><h1 class="text-xl font-bold sm:text-2xl">{{ workspace?.name || t("workspaces.detailTitle") }}</h1><p class="text-sm text-base-content/55">@{{ workspace?.slug }}</p></div></div><p class="mt-3 max-w-2xl text-sm text-base-content/60">{{ workspace?.description || t("workspaces.noDescription") }}</p></div></div>
        <button class="btn btn-ghost btn-sm" type="button" :disabled="loading" @click="loadWorkspace"><IconRefreshCw class="h-4 w-4" :class="{ 'animate-spin': loading }" />{{ t("workspaces.refresh") }}</button>
      </header>

      <section v-if="loading && !workspace" class="flex justify-center py-16"><ConfuseSpinner :message="t('workspaces.loading')" /></section>
      <section v-else-if="loadError" class="workspace-panel px-5 py-12 text-center"><IconAlertCircle class="mx-auto h-6 w-6 text-error" /><p class="mt-3 text-sm text-error">{{ loadError }}</p><button class="btn btn-ghost btn-sm mt-4" type="button" @click="loadWorkspace">{{ t("workspaces.refresh") }}</button></section>
      <template v-else-if="workspace">
        <div class="tabs tabs-bordered overflow-x-auto" role="tablist"><button v-for="tab in tabs" :key="tab.id" class="tab whitespace-nowrap" :class="{ 'tab-active': activeTab === tab.id }" role="tab" type="button" @click="activeTab = tab.id">{{ tab.label }}</button></div>

        <section v-if="activeTab === 'overview'" class="grid gap-4 md:grid-cols-3"><article class="workspace-panel p-5"><p class="text-xs uppercase text-base-content/50">{{ t("workspaces.workspaceType") }}</p><p class="mt-2 text-lg font-semibold">{{ typeLabel(workspace) }}</p><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.slug") }}: @{{ workspace.slug }}</p></article><article class="workspace-panel p-5"><p class="text-xs uppercase text-base-content/50">{{ t("workspaces.currentPlan") }}</p><p class="mt-2 text-lg font-semibold">{{ planLabel(workspace) }}</p><p class="mt-1 text-sm text-base-content/55">{{ workspace.isBundled ? t("workspaces.bundledPlan") : t("workspaces.paidPlan") }}</p><button class="btn btn-outline btn-sm mt-4" type="button" @click="activeTab = 'plan'">{{ t("workspaces.managePlan") }}</button></article><article class="workspace-panel p-5"><p class="text-xs uppercase text-base-content/50">{{ t("workspaces.management") }}</p><p class="mt-2 text-lg font-semibold">{{ members.length }} {{ t("workspaces.members").toLowerCase() }}</p><p class="mt-1 text-sm text-base-content/55">{{ mailboxes.length }} {{ t("workspaces.mailboxes").toLowerCase() }}</p><div class="mt-4 flex gap-2"><button class="btn btn-ghost btn-sm" type="button" @click="activeTab = 'members'">{{ t("workspaces.members") }}</button><button class="btn btn-ghost btn-sm" type="button" @click="activeTab = 'mailboxes'">{{ t("workspaces.mailboxes") }}</button></div></article></section>

        <section v-if="activeTab === 'plan'" class="workspace-panel p-5"><div class="flex items-start justify-between gap-3"><div><h2 class="text-lg font-bold">{{ t("workspaces.managePlan") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.planDescription") }}</p></div><span class="badge badge-lg">{{ selectedPlanLabel }}</span></div><div v-if="planLoading" class="py-12 text-center"><span class="loading loading-spinner" /></div><div v-else class="mt-6 grid gap-3 sm:grid-cols-2"><button v-if="(selectedPlan?.plan ?? workspace.plan) < WorkspacePlan.pro" class="btn btn-outline h-auto justify-start p-4 text-left" type="button" :disabled="isSubscribing" @click="purchasePlan(WorkspacePlan.pro)"><span><strong class="block">{{ t("workspaces.pro") }}</strong><span class="text-xs text-base-content/55">{{ t("workspaces.upgradeToPro") }}</span></span></button><button v-if="(selectedPlan?.plan ?? workspace.plan) < WorkspacePlan.enterprise" class="btn btn-primary h-auto justify-start p-4 text-left" type="button" :disabled="isSubscribing" @click="purchasePlan(WorkspacePlan.enterprise)"><span><strong class="block">{{ t("workspaces.enterprise") }}</strong><span class="text-xs opacity-70">{{ t("workspaces.upgradeToEnterprise") }}</span></span></button></div><p v-if="planError" class="mt-4 text-sm text-error">{{ planError }}</p></section>

        <section v-if="activeTab === 'members'" class="workspace-panel p-5"><div class="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 class="text-lg font-bold">{{ t("workspaces.members") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.membersDescription") }}</p></div><button class="btn btn-primary btn-sm" type="button" @click="showInviteDialog = true"><IconUserPlus class="h-4 w-4" />{{ t("workspaces.invite") }}</button></div><div v-if="membersLoading" class="py-12 text-center"><span class="loading loading-spinner" /></div><p v-else-if="membersError" class="mt-5 text-sm text-error">{{ membersError }}</p><div v-else class="mt-5 divide-y divide-base-300"> <div v-for="member in members" :key="member.id" class="flex flex-wrap items-center gap-3 py-3"><div class="flex h-9 w-9 shrink-0 items-center justify-center overflow-hidden rounded-full bg-primary/10 font-semibold text-primary"><img v-if="memberAvatarUrl(member)" :src="memberAvatarUrl(member)!" :alt="memberLabel(member)" class="h-full w-full object-cover" @error="handleAvatarError" /><span class="hidden">{{ memberLabel(member).slice(0, 1).toUpperCase() }}</span><span v-if="!memberAvatarUrl(member)">{{ memberLabel(member).slice(0, 1).toUpperCase() }}</span></div><div class="min-w-0 flex-1"><p class="truncate text-sm font-medium">{{ memberLabel(member) }}</p><p class="truncate text-xs text-base-content/50">{{ memberEmail(member) || member.accountId }}</p></div><select class="select select-bordered select-sm w-28" :value="member.role" :disabled="member.role >= 100 || memberBusy === member.accountId" @change="changeRole(member, Number(($event.target as HTMLSelectElement).value))"><option v-for="role in roles" :key="role.value" :value="role.value">{{ role.label }}</option></select><button v-if="member.role < 100" class="btn btn-ghost btn-sm text-error" type="button" :disabled="memberBusy === member.accountId" @click="removeMember(member)"><IconTrash2 class="h-4 w-4" /></button></div><p v-if="!members.length" class="py-8 text-center text-sm text-base-content/55">{{ t("workspaces.noMembers") }}</p></div></section>

        <section v-if="activeTab === 'mailboxes'" class="space-y-4"><article class="workspace-panel p-5"><div class="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 class="text-lg font-bold">{{ t("workspaces.mailboxes") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.mailboxesDescription") }}</p></div><button class="btn btn-primary btn-sm" type="button" @click="showMailboxDialog = true"><IconPlus class="h-4 w-4" />{{ t("workspaces.addMailbox") }}</button></div><div v-if="mailboxesLoading" class="py-12 text-center"><span class="loading loading-spinner" /></div><p v-else-if="mailboxesError" class="mt-5 text-sm text-error">{{ mailboxesError }}</p><div v-else class="mt-5 divide-y divide-base-300"><div v-for="mailbox in mailboxes" :key="mailbox.id" class="flex items-center gap-3 py-3"><IconMail class="h-5 w-5 text-primary" /><div class="min-w-0 flex-1"><p class="truncate text-sm font-medium">{{ mailbox.name || fullMailboxAddress(mailbox.address) }}</p><p class="truncate text-xs text-base-content/55">{{ fullMailboxAddress(mailbox.address) }}<span v-if="mailbox.isDefault"> · {{ t("workspaces.defaultMailbox") }}</span></p></div><span v-if="mailbox.isVerified" class="badge badge-success badge-sm">{{ t("workspaces.verified") }}</span></div><p v-if="!mailboxes.length" class="py-8 text-center text-sm text-base-content/55">{{ t("workspaces.noMailboxes") }}</p></div></article><article class="workspace-panel p-5"><div class="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 class="text-lg font-bold">{{ t("workspaces.mailCredentials") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.mailCredentialsDescription") }}</p></div><button class="btn btn-outline btn-sm" type="button" :disabled="!mailboxes.length" @click="showCredentialDialog = true"><IconKeyRound class="h-4 w-4" />{{ t("workspaces.createCredential") }}</button></div><div class="mt-5 rounded-md border border-base-300 bg-base-200/30 p-4"><div class="flex items-start gap-3"><IconSettings2 class="mt-0.5 h-5 w-5 shrink-0 text-primary" /><div class="min-w-0 flex-1"><h3 class="text-sm font-semibold">{{ t("workspaces.clientConfiguration") }}</h3><p class="mt-1 text-xs text-base-content/55">{{ t("workspaces.clientConfigurationDescription") }}</p><div class="mt-4 overflow-x-auto"><table class="table table-sm"><thead><tr><th>{{ t("workspaces.service") }}</th><th>{{ t("workspaces.server") }}</th><th>{{ t("workspaces.port") }}</th><th>{{ t("workspaces.security") }}</th></tr></thead><tbody><tr v-for="config in mailClientConfigurations" :key="`${config.service}-${config.port}`"><td class="font-medium">{{ config.service }}</td><td><code>{{ config.server }}</code></td><td><code>{{ config.port }}</code></td><td>{{ config.security }}</td></tr></tbody></table></div><p class="mt-3 text-xs text-base-content/55">{{ t("workspaces.clientUsernameHint") }}</p></div></div></div><div v-if="credentialsLoading" class="py-10 text-center"><span class="loading loading-spinner" /></div><p v-else-if="credentialsError" class="mt-4 text-sm text-error">{{ credentialsError }}</p><div v-else class="mt-4 divide-y divide-base-300"><div v-for="credential in workspaceCredentials" :key="credential.id" class="flex items-center gap-3 py-3"><IconKeyRound class="h-5 w-5 text-primary" /><div class="min-w-0 flex-1"><p class="truncate text-sm font-medium">{{ credential.label }}</p><p class="truncate text-xs text-base-content/55">{{ mailboxAddress(credential.mailboxId) }} · {{ credential.protocols.map((protocol) => protocol.toUpperCase()).join(', ') }}</p></div><button class="btn btn-ghost btn-sm text-error" type="button" @click="revokeCredential(credential)"><IconTrash2 class="h-4 w-4" /></button></div><p v-if="!workspaceCredentials.length" class="py-8 text-center text-sm text-base-content/55">{{ t("workspaces.noCredentials") }}</p></div></article></section>

        <section v-if="activeTab === 'flywheel'" class="workspace-panel p-5"><div class="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 class="text-lg font-bold">{{ t("workspaces.flywheel") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.flywheelDescription") }}</p></div><span v-if="flywheelQuota" class="text-sm font-semibold">{{ formatQuotaBytes(flywheelQuota.usedBytes) }} / {{ formatQuotaBytes(flywheelQuota.budgetBytes) }}</span></div><div v-if="flywheelQuota" class="mt-4"><progress class="progress progress-primary w-full h-2" :value="flywheelQuota.usedBytes" :max="flywheelQuota.budgetBytes" /><p class="mt-2 text-xs text-base-content/55">{{ t("workspaces.flywheelQuotaDescription") }}</p></div><div v-if="flywheelLoading" class="py-12 text-center"><span class="loading loading-spinner" /></div><p v-else-if="flywheelError" class="mt-5 text-sm text-error">{{ flywheelError }}</p><div v-else class="mt-5 space-y-3"><article v-for="app in flywheelApps" :key="app.appId" class="rounded-md border border-base-300 p-4"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h3 class="font-semibold">{{ app.appId }}</h3><p class="mt-1 text-xs text-base-content/55">{{ app.blobCount }} {{ t("workspaces.saves") }} · {{ app.retainedRevisionCountTotal }} {{ t("workspaces.revisions") }} · {{ formatBytes(app.retainedBytes) }}</p></div><button class="btn btn-ghost btn-sm" type="button" @click="openFlywheelApp(app)">{{ t("workspaces.details") }}</button></div></article><p v-if="!flywheelApps.length" class="py-8 text-center text-sm text-base-content/55">{{ t("workspaces.noFlywheel") }}</p></div></section>
        <section v-if="activeTab === 'mailboxes'" class="workspace-panel p-5"><div class="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 class="text-lg font-bold">{{ t("workspaces.mailboxRouting") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.mailboxRoutingDescription") }}</p></div><select class="select select-bordered select-sm" :value="selectedMailbox?.id || ''" @change="openMailboxDetails(mailboxes.find((mailbox) => mailbox.id === ($event.target as HTMLSelectElement).value)!)"><option disabled value="">{{ t("workspaces.selectMailbox") }}</option><option v-for="mailbox in mailboxes" :key="mailbox.id" :value="mailbox.id">{{ fullMailboxAddress(mailbox.address) }}</option></select></div><div v-if="mailboxDetailsLoading" class="py-8 text-center"><span class="loading loading-spinner" /></div><p v-else-if="mailboxDetailsError" class="mt-4 text-sm text-error">{{ mailboxDetailsError }}</p><div v-else-if="selectedMailbox" class="mt-5 grid gap-6 lg:grid-cols-2"><div><h3 class="font-semibold">{{ t("workspaces.aliases") }}</h3><form class="mt-3 space-y-3" @submit.prevent="createAlias"><select v-model="aliasDraft.customDomainId" class="select select-bordered w-full" required><option disabled value="">{{ t("workspaces.selectCustomDomain") }}</option><option v-for="domain in customDomains.filter((item) => item.verifiedForSendingStatus)" :key="domain.id" :value="domain.id">{{ domain.domain }}</option></select><input v-model.trim="aliasDraft.localPart" class="input w-full" :placeholder="t('workspaces.aliasLocalPart')" required /><input v-model.trim="aliasDraft.name" class="input w-full" :placeholder="t('workspaces.aliasName')" /><button class="btn btn-outline btn-sm" type="submit" :disabled="aliasSaving || !customDomains.some((domain) => domain.verifiedForSendingStatus)"><IconPlus class="h-4 w-4" />{{ t("workspaces.addAlias") }}</button></form><div class="mt-4 divide-y divide-base-300"><div v-for="alias in mailboxAliases" :key="alias.id" class="flex items-center gap-3 py-3"><div class="min-w-0 flex-1"><p class="truncate text-sm font-medium">{{ alias.address }}</p><p v-if="alias.name" class="truncate text-xs text-base-content/50">{{ alias.name }}</p></div><button class="btn btn-ghost btn-sm text-error" type="button" @click="removeAlias(alias)"><IconTrash2 class="h-4 w-4" /></button></div><p v-if="!mailboxAliases.length" class="py-5 text-sm text-base-content/55">{{ t("workspaces.noAliases") }}</p></div></div><div><h3 class="font-semibold">{{ t("workspaces.forwarding") }}</h3><form class="mt-3 space-y-3" @submit.prevent="createForwarding"><select v-model="forwardingDraft.aliasId" class="select select-bordered w-full" required><option disabled value="">{{ t("workspaces.selectAlias") }}</option><option v-for="alias in mailboxAliases" :key="alias.id" :value="alias.id">{{ alias.address }}</option></select><input v-model.trim="forwardingDraft.destination" class="input w-full" type="email" :placeholder="t('workspaces.forwardingDestination')" required /><button class="btn btn-outline btn-sm" type="submit" :disabled="forwardingSaving || !mailboxAliases.length"><IconPlus class="h-4 w-4" />{{ t("workspaces.addForwarding") }}</button></form><div class="mt-4 divide-y divide-base-300"><div v-for="rule in mailboxForwarding" :key="rule.id" class="flex items-center gap-3 py-3"><div class="min-w-0 flex-1"><p class="truncate text-sm font-medium">{{ rule.destination }}</p><p class="truncate text-xs text-base-content/50">{{ mailboxAliases.find((alias) => alias.id === rule.aliasId)?.address || rule.aliasId }}</p></div><button class="btn btn-ghost btn-sm text-error" type="button" @click="removeForwarding(rule)"><IconTrash2 class="h-4 w-4" /></button></div><p v-if="!mailboxForwarding.length" class="py-5 text-sm text-base-content/55">{{ t("workspaces.noForwarding") }}</p></div></div></div></section>
         <section v-if="activeTab === 'mailboxes'" class="workspace-panel p-5"><h2 class="text-lg font-bold">{{ t("workspaces.customDomains") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.customDomainsDescription") }}</p><div v-if="customDomainsLoading" class="py-6 text-center"><span class="loading loading-spinner" /></div><div v-else class="mt-4 space-y-3"><article v-for="domain in customDomains" :key="domain.id" class="border-b border-base-300 pb-3"><div class="flex flex-wrap items-center justify-between gap-2"><div><p class="font-medium">{{ domain.domain }}</p><p class="text-xs text-base-content/55">{{ domain.verificationStatus }} · {{ domain.verifiedForSendingStatus ? t("workspaces.readyForSending") : t("workspaces.dnsVerificationRequired") }}</p></div><div class="flex gap-2"><button class="btn btn-ghost btn-sm" type="button" @click="refreshCustomDomain(domain)"><IconRefreshCw class="h-4 w-4" />{{ t("workspaces.refresh") }}</button><button class="btn btn-ghost btn-sm text-error" type="button" @click="removeCustomDomain(domain)"><IconTrash2 class="h-4 w-4" /></button></div></div><div v-if="domain.dnsRecords?.length" class="mt-3 overflow-x-auto"><table class="table table-sm"><tbody><tr v-for="record in domain.dnsRecords" :key="`${record.name}-${record.value}`"><td><code>{{ record.name }}</code></td><td>{{ record.type }}</td><td><code>{{ record.value }}</code></td></tr></tbody></table></div></article><button class="btn btn-outline btn-sm" type="button" @click="showCustomDomainDialog = true"><IconPlus class="h-4 w-4" />{{ t("workspaces.addCustomDomain") }}</button></div></section>
         <section v-if="activeTab === 'mailboxes' && selectedMailbox && mailboxQuota" class="workspace-panel p-5"><div class="flex items-center justify-between gap-3"><div><h2 class="text-lg font-bold">{{ t("workspaces.mailboxQuota") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.mailboxQuotaDescription") }}</p></div><span class="text-sm font-semibold">{{ formatQuotaBytes(mailboxQuota.remainingBytes) }} {{ t("workspaces.remaining") }}</span></div><div class="mt-4 grid gap-3 sm:grid-cols-3"><div><p class="text-xs text-base-content/50">{{ t("workspaces.used") }}</p><p class="mt-1 font-medium">{{ formatQuotaBytes(mailboxQuota.usedBytes) }}</p></div><div><p class="text-xs text-base-content/50">{{ t("workspaces.limit") }}</p><p class="mt-1 font-medium">{{ formatQuotaBytes(mailboxQuota.limitBytes) }}</p></div><div><p class="text-xs text-base-content/50">{{ t("workspaces.remaining") }}</p><p class="mt-1 font-medium">{{ formatQuotaBytes(mailboxQuota.remainingBytes) }}</p></div></div></section>
         <details v-if="activeTab === 'mailboxes'" class="workspace-panel p-5"><summary class="cursor-pointer text-lg font-bold">{{ t("workspaces.clientConfiguration") }}</summary><p class="mt-2 text-sm text-base-content/55">{{ t("workspaces.clientConfigurationDescription") }}</p><div class="mt-4 overflow-x-auto"><table class="table table-sm"><thead><tr><th>{{ t("workspaces.service") }}</th><th>{{ t("workspaces.server") }}</th><th>{{ t("workspaces.port") }}</th><th>{{ t("workspaces.security") }}</th></tr></thead><tbody><tr v-for="config in mailClientConfigurations" :key="`${config.service}-${config.port}`"><td class="font-medium">{{ config.service }}</td><td><code>{{ config.server }}</code></td><td><code>{{ config.port }}</code></td><td>{{ config.security }}</td></tr></tbody></table></div><p class="mt-3 text-xs text-base-content/55">{{ t("workspaces.clientUsernameHint") }}</p></details>
         <section v-if="activeTab === 'mailboxes' && workspace" class="workspace-panel p-5"><div class="flex items-center justify-between gap-3"><div><h2 class="text-lg font-bold">{{ t("workspaces.mailboxUsage") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.mailboxUsageDescription") }}</p></div><span v-if="mailboxUsage" class="text-sm font-semibold">{{ mailboxUsage.used }} / {{ mailboxUsage.limit }}</span></div><div v-if="mailboxUsageLoading" class="py-6 text-center"><span class="loading loading-spinner" /></div><p v-else-if="mailboxUsageError" class="mt-4 text-sm text-error">{{ mailboxUsageError }}</p><div v-else-if="mailboxUsage" class="mt-4 grid gap-3 sm:grid-cols-3"><div><p class="text-xs text-base-content/50">{{ t("workspaces.used") }}</p><p class="mt-1 font-medium">{{ mailboxUsage.used }}</p></div><div><p class="text-xs text-base-content/50">{{ t("workspaces.limit") }}</p><p class="mt-1 font-medium">{{ mailboxUsage.limit }}</p></div><div><p class="text-xs text-base-content/50">{{ t("workspaces.remaining") }}</p><p class="mt-1 font-medium" :class="{ 'text-error': mailboxUsage.remaining === 0 }">{{ mailboxUsage.remaining }}</p></div></div></section>
         <section v-if="activeTab === 'mailboxes' && sendUsage" class="workspace-panel p-5"><h2 class="text-lg font-bold">{{ t("workspaces.sendUsage") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.sendUsageDescription") }}</p><div class="mt-4 grid gap-3 md:grid-cols-2"><div v-for="period in [{ id: 'daily', label: t('workspaces.daily'), usage: sendUsage.daily }, { id: 'monthly', label: t('workspaces.monthly'), usage: sendUsage.monthly }]" :key="period.id" class="rounded-md border border-base-300 p-4"><div class="flex items-center justify-between gap-3"><p class="font-medium">{{ period.label }}</p><span v-if="period.usage.limit === 0" class="badge badge-ghost badge-sm">{{ t("workspaces.disabled") }}</span><span v-else class="text-sm font-semibold" :class="{ 'text-error': period.usage.remaining === 0 }">{{ period.usage.remaining }} {{ t("workspaces.remaining").toLowerCase() }}</span></div><div class="mt-3 grid grid-cols-2 gap-3 text-sm"><div><p class="text-xs text-base-content/50">{{ t("workspaces.used") }}</p><p class="mt-1 font-medium">{{ period.usage.used }}</p></div><div><p class="text-xs text-base-content/50">{{ t("workspaces.limit") }}</p><p class="mt-1 font-medium">{{ period.usage.limit === 0 ? t("workspaces.disabled") : period.usage.limit }}</p></div></div></div></div></section>
         <section v-if="activeTab === 'mailboxes'" class="workspace-panel p-5"><div class="flex items-center justify-between gap-3"><div><h2 class="text-lg font-bold">{{ t("workspaces.customDomains") }}</h2><p class="mt-1 text-sm text-base-content/55">{{ t("workspaces.customDomainsDescription") }}</p></div><button class="btn btn-primary btn-sm" type="button" :disabled="customDomainUsage?.remaining === 0" @click="showCustomDomainDialog = true"><IconPlus class="h-4 w-4" />{{ t("workspaces.addCustomDomain") }}</button></div><p v-if="customDomainUsage" class="mt-4 text-sm text-base-content/60">{{ customDomainUsage.used }} / {{ customDomainUsage.limit }} {{ t("workspaces.customDomains").toLowerCase() }} · {{ customDomainUsage.remaining }} {{ t("workspaces.remaining").toLowerCase() }}</p><div v-if="customDomainsLoading" class="py-8 text-center"><span class="loading loading-spinner" /></div><p v-else-if="customDomainsError" class="mt-4 text-sm text-error">{{ customDomainsError }}</p><div v-else class="mt-5 space-y-4"><article v-for="domain in customDomains" :key="domain.id" class="border-b border-base-300 pb-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><div class="flex items-center gap-2"><p class="font-semibold">{{ domain.domain }}</p><span class="badge badge-sm">{{ t(`workspaces.domainStage${domain.stage.charAt(0).toUpperCase()}${domain.stage.slice(1)}`) }}</span></div><p class="mt-1 text-xs text-base-content/55">DKIM: {{ domain.dkimStatus }} · MAIL FROM: {{ domain.mailFromStatus }}</p></div><div class="flex gap-2"><button class="btn btn-ghost btn-sm" type="button" :disabled="customDomainBusy === domain.id" @click="refreshCustomDomain(domain)"><IconRefreshCw class="h-4 w-4" :class="{ 'animate-spin': customDomainBusy === domain.id }" />{{ t("workspaces.refresh") }}</button><button class="btn btn-ghost btn-sm text-error" type="button" :disabled="customDomainBusy === domain.id" @click="removeCustomDomain(domain)"><IconTrash2 class="h-4 w-4" /></button></div></div><details class="mt-4"><summary class="cursor-pointer text-sm font-medium">{{ t("workspaces.dnsRecords") }}</summary><div class="mt-3 space-y-4"><div v-for="group in [{ id: 'dkim', label: t('workspaces.dkimRecords') }, { id: 'mailFrom', label: t('workspaces.mailFromRecords') }, { id: 'inbound', label: t('workspaces.inboundRecords') }]" :key="group.id"><p class="text-xs font-medium text-base-content/60">{{ group.label }}</p><div class="mt-2 overflow-x-auto rounded-md border border-base-300"><table class="table table-sm"><thead><tr><th>{{ t("workspaces.recordName") }}</th><th>{{ t("workspaces.recordType") }}</th><th>{{ t("workspaces.recordValue") }}</th></tr></thead><tbody><tr v-for="record in customDomainRecords(domain, group.id as 'dkim' | 'mailFrom' | 'inbound')" :key="`${record.name}-${record.value}`"><td><code>{{ record.name }}</code></td><td>{{ record.type }}</td><td><code>{{ record.value }}</code></td></tr><tr v-if="!customDomainRecords(domain, group.id as 'dkim' | 'mailFrom' | 'inbound').length"><td colspan="3" class="text-base-content/50">{{ t("workspaces.noRecords") }}</td></tr></tbody></table></div></div></div></details></article><p v-if="!customDomains.length" class="py-6 text-center text-sm text-base-content/55">{{ t("workspaces.noCustomDomains") }}</p></div></section>
         </template>
    </div>

    <dialog class="modal" :class="{ 'modal-open': showInviteDialog }"><div class="modal-box"><button class="btn btn-sm btn-circle btn-ghost absolute right-2 top-2" type="button" @click="showInviteDialog = false"><IconX class="h-5 w-5" /></button><h2 class="text-lg font-bold">{{ t("workspaces.invite") }}</h2><fieldset class="fieldset mt-4"><legend class="fieldset-legend">{{ t("workspaces.searchAccounts") }}</legend><input v-model="accountQuery" class="input w-full" :placeholder="t('workspaces.searchAccounts')" @input="searchForAccounts" /><p class="label">{{ t("workspaces.searchAccountsHint") }}</p></fieldset><div class="mt-3 max-h-56 overflow-y-auto divide-y divide-base-300"><button v-for="account in accountResults" :key="account.id" class="flex w-full items-center gap-3 py-3 text-left" type="button" @click="inviteAccount = account"><span class="flex h-8 w-8 items-center justify-center rounded-full bg-primary/10 font-semibold text-primary">{{ (account.nick || account.name).slice(0, 1).toUpperCase() }}</span><span class="min-w-0 flex-1"><span class="block truncate text-sm font-medium">{{ account.nick || account.name }}</span><span class="block truncate text-xs text-base-content/50">{{ account.name }}{{ account.contacts?.find((contact) => contact.isPrimary)?.content ? ` · ${account.contacts.find((contact) => contact.isPrimary)?.content}` : '' }}</span></span><IconCheck v-if="inviteAccount?.id === account.id" class="h-4 w-4 text-primary" /></button></div><fieldset class="fieldset mt-4"><legend class="fieldset-legend">{{ t("workspaces.role") }}</legend><select v-model.number="inviteRole" class="select w-full"><option v-for="role in roles.filter((item) => item.value < 100)" :key="role.value" :value="role.value">{{ role.label }}</option></select></fieldset><p v-if="memberActionError" class="mt-3 text-sm text-error">{{ memberActionError }}</p><div class="modal-action"><button class="btn btn-ghost" type="button" @click="showInviteDialog = false">{{ t("realms.cancel") }}</button><button class="btn btn-primary" type="button" :disabled="!inviteAccount || memberBusy === 'invite'" @click="inviteSelectedAccount"><IconLoader v-if="memberBusy === 'invite'" class="h-4 w-4 animate-spin" />{{ t("workspaces.invite") }}</button></div></div></dialog>
    <dialog class="modal" :class="{ 'modal-open': showMailboxDialog }"><div class="modal-box"><button class="btn btn-sm btn-circle btn-ghost absolute right-2 top-2" type="button" @click="showMailboxDialog = false"><IconX class="h-5 w-5" /></button><h2 class="text-lg font-bold">{{ t("workspaces.addMailbox") }}</h2><form class="mt-5 space-y-4" @submit.prevent="createMailbox"><fieldset class="fieldset"><legend class="fieldset-legend">{{ t("workspaces.mailboxAddress") }}</legend><input v-model.trim="mailboxDraft.address" class="input w-full" required /><p class="label">{{ t("workspaces.mailboxAddressHint") }}</p></fieldset><fieldset class="fieldset"><legend class="fieldset-legend">{{ t("workspaces.mailboxName") }}</legend><input v-model.trim="mailboxDraft.name" class="input w-full" /><p class="label">{{ t("workspaces.mailboxNameHint") }}</p></fieldset><label class="label cursor-pointer justify-start gap-3"><input v-model="mailboxDraft.isDefault" type="checkbox" class="checkbox checkbox-sm" /><span class="label-text">{{ t("workspaces.makeDefault") }}</span></label><p v-if="mailboxesError" class="text-sm text-error">{{ mailboxesError }}</p><div class="modal-action"><button class="btn btn-ghost" type="button" @click="showMailboxDialog = false">{{ t("realms.cancel") }}</button><button class="btn btn-primary" type="submit" :disabled="mailboxSaving"><IconLoader v-if="mailboxSaving" class="h-4 w-4 animate-spin" />{{ t("workspaces.addMailbox") }}</button></div></form></div></dialog>
    <dialog class="modal" :class="{ 'modal-open': showCredentialDialog }"><div class="modal-box"><button class="btn btn-sm btn-circle btn-ghost absolute right-2 top-2" type="button" @click="showCredentialDialog = false"><IconX class="h-5 w-5" /></button><h2 class="text-lg font-bold">{{ t("workspaces.createCredential") }}</h2><form class="mt-5 space-y-4" @submit.prevent="createCredential"><fieldset class="fieldset"><legend class="fieldset-legend">{{ t("workspaces.credentialLabel") }}</legend><input v-model.trim="credentialDraft.label" class="input w-full" required /><p class="label">{{ t("workspaces.credentialLabelHint") }}</p></fieldset><fieldset class="fieldset"><legend class="fieldset-legend">{{ t("workspaces.credentialMailbox") }}</legend><select v-model="credentialDraft.mailboxId" class="select w-full" required><option disabled value="">{{ t("workspaces.selectMailbox") }}</option><option v-for="mailbox in mailboxes" :key="mailbox.id" :value="mailbox.id">{{ mailbox.name || mailbox.address }}</option></select></fieldset><fieldset class="fieldset"><legend class="fieldset-legend">{{ t("workspaces.credentialProtocols") }}</legend><div class="flex flex-wrap gap-3"><label v-for="protocol in credentialProtocols" :key="protocol" class="label cursor-pointer gap-2"><input v-model="credentialDraft.protocols" :value="protocol" type="checkbox" class="checkbox checkbox-sm" /><span>{{ protocol.toUpperCase() }}</span></label></div><p class="label">{{ t("workspaces.credentialProtocolsHint") }}</p></fieldset><p v-if="credentialsError" class="text-sm text-error">{{ credentialsError }}</p><div class="modal-action"><button class="btn btn-ghost" type="button" @click="showCredentialDialog = false">{{ t("realms.cancel") }}</button><button class="btn btn-primary" type="submit" :disabled="credentialSaving || !credentialDraft.protocols.length"><IconLoader v-if="credentialSaving" class="h-4 w-4 animate-spin" />{{ t("workspaces.createCredential") }}</button></div></form></div></dialog>
    <dialog class="modal" :class="{ 'modal-open': createdCredentialSecret }"><div class="modal-box"><h2 class="text-lg font-bold">{{ t("workspaces.credentialCreated") }}</h2><p class="mt-2 text-sm text-base-content/60">{{ t("workspaces.saveSecretOnce") }}</p><div class="mt-4 rounded-md border border-warning/40 bg-warning/10 p-4"><code class="select-all break-all text-sm font-semibold">{{ createdCredentialSecret }}</code></div><div class="modal-action"><button class="btn btn-primary" type="button" @click="createdCredentialSecret = null">{{ t("realms.done") }}</button></div></div></dialog>
    <dialog class="modal" :class="{ 'modal-open': selectedFlywheelApp }"><div class="modal-box max-w-2xl"><button class="btn btn-sm btn-circle btn-ghost absolute right-2 top-2" type="button" @click="selectedFlywheelApp = null"><IconX class="h-5 w-5" /></button><h2 class="text-lg font-bold">{{ selectedFlywheelApp?.appId }}</h2><div v-if="flywheelDetailLoading" class="py-10 text-center"><span class="loading loading-spinner loading-sm" /></div><div v-else class="mt-5"><div role="tablist" class="tabs tabs-bordered"><button role="tab" class="tab" :class="{ 'tab-active': flywheelTab === 'saves' }" type="button" @click="flywheelTab = 'saves'">{{ t("workspaces.saves") }}</button><button role="tab" class="tab" :class="{ 'tab-active': flywheelTab === 'audit' }" type="button" @click="flywheelTab = 'audit'">{{ t("workspaces.audit") }}</button></div><div v-if="flywheelTab === 'saves'" class="mt-3 divide-y divide-base-300"><div v-for="blob in flywheelBlobs" :key="blob.blobId" class="flex items-center gap-3 py-3 text-sm"><div class="min-w-0 flex-1"><p class="truncate font-medium">{{ blob.blobId }}</p><p class="text-xs text-base-content/55">{{ t("workspaces.revision") }} {{ blob.currentRevision }} · {{ formatBytes(blob.retainedBytes) }}</p></div><button class="btn btn-ghost btn-sm text-error" type="button" @click="deleteBlob(blob)"><IconTrash2 class="h-4 w-4" /></button></div><p v-if="!flywheelBlobs.length" class="py-8 text-center text-sm text-base-content/55">{{ t("workspaces.noSaves") }}</p></div><div v-else class="mt-3 divide-y divide-base-300"><div v-for="entry in flywheelAudit" :key="`${entry.createdAt}-${entry.action}`" class="flex justify-between gap-3 py-2 text-xs"><span>{{ entry.action }} · {{ entry.actorAccountId }}</span><time class="text-base-content/50">{{ formatDate(entry.createdAt) }}</time></div><p v-if="!flywheelAudit.length" class="py-8 text-center text-sm text-base-content/55">{{ t("workspaces.noAudit") }}</p></div></div></div></dialog>
     <dialog class="modal" :class="{ 'modal-open': showCustomDomainDialog }"><div class="modal-box"><button class="btn btn-sm btn-circle btn-ghost absolute right-2 top-2" type="button" @click="showCustomDomainDialog = false"><IconX class="h-5 w-5" /></button><h2 class="text-lg font-bold">{{ t("workspaces.addCustomDomain") }}</h2><form class="mt-5 space-y-4" @submit.prevent="createCustomDomain"><fieldset class="fieldset"><legend class="fieldset-legend">{{ t("workspaces.customDomain") }}</legend><input v-model.trim="customDomainDraft" class="input w-full" placeholder="example.com" required /><p class="label">{{ t("workspaces.customDomainHint") }}</p></fieldset><p v-if="customDomainsError" class="text-sm text-error">{{ customDomainsError }}</p><div class="modal-action"><button class="btn btn-ghost" type="button" @click="showCustomDomainDialog = false">{{ t("realms.cancel") }}</button><button class="btn btn-primary" type="submit" :disabled="customDomainSaving"><IconLoader v-if="customDomainSaving" class="h-4 w-4 animate-spin" />{{ t("workspaces.addCustomDomain") }}</button></div></form></div></dialog>
   </NuxtLayout>
</template>

<script setup lang="ts">
import type { SnAccount } from "~/types/auth";
import type { FlywheelAuditEntry, FlywheelOwnerApp, FlywheelOwnerBlob, FlywheelStorageQuota, Workspace, WorkspaceCustomDomain, WorkspaceCustomDomainUsage, WorkspaceMailbox, WorkspaceMailboxAlias, WorkspaceMailboxForwardingRule, WorkspaceMailboxQuota, WorkspaceMailboxUsage, WorkspaceMailCredential, WorkspaceMailCredentialCreated, WorkspaceMember, WorkspacePlanStatus, WorkspaceSendUsage } from "~/types/workspace";
import { WorkspacePlan, WorkspaceType } from "~/types/workspace";
import { createMailboxAlias, createMailboxForwarding, createMailCredential, createWorkspaceCustomDomain, createWorkspaceMailbox, deleteFlywheelBlob, deleteMailboxAlias, deleteMailboxForwarding, deleteWorkspaceCustomDomain, fetchFlywheelApps, fetchFlywheelAudit, fetchFlywheelBlobs, fetchFlywheelStorageQuota, fetchMailboxAliases, fetchMailboxForwarding, fetchMailboxQuota, fetchMailCredentials, fetchMailHost, fetchWorkspaceCustomDomains, fetchWorkspaceCustomDomainUsage, fetchWorkspaceMailboxUsage, fetchWorkspaceMailboxes, fetchWorkspaceMembers, fetchWorkspacePlanStatus, fetchWorkspaceSendUsage, fetchWorkspaces, inviteWorkspaceMember, refreshWorkspaceCustomDomain, removeWorkspaceMember, revokeMailCredential, searchAccounts, subscribeWorkspacePlan, updateWorkspaceMemberRole } from "~/utils/api";
import { getFileUrl } from "~/utils/files";
import { IconAlertCircle, IconArrowLeft, IconCheck, IconKeyRound, IconLoader, IconMail, IconPlus, IconRefreshCw, IconSettings2, IconTrash2, IconUserPlus, IconX } from "#components";

definePageMeta({ middleware: "auth" });
const { t } = useI18n();
const route = useRoute();
const slug = computed(() => route.params.slug as string);
const workspace = ref<Workspace | null>(null);
const loading = ref(true);
const loadError = ref<string | null>(null);
const activeTab = ref<"overview" | "plan" | "members" | "mailboxes" | "flywheel">("overview");
const selectedPlan = ref<WorkspacePlanStatus | null>(null);
const planLoading = ref(false);
const planError = ref<string | null>(null);
const isSubscribing = ref(false);
const members = ref<WorkspaceMember[]>([]);
const membersLoading = ref(false);
const membersError = ref<string | null>(null);
const memberActionError = ref<string | null>(null);
const memberBusy = ref<string | null>(null);
const showInviteDialog = ref(false);
const accountQuery = ref("");
const accountResults = ref<SnAccount[]>([]);
const inviteAccount = ref<SnAccount | null>(null);
const inviteRole = ref(50);
const mailboxes = ref<WorkspaceMailbox[]>([]);
const mailboxUsage = ref<WorkspaceMailboxUsage | null>(null);
const mailboxUsageLoading = ref(false);
const mailboxUsageError = ref<string | null>(null);
const sendUsage = ref<WorkspaceSendUsage | null>(null);
const mailboxesLoading = ref(false);
const mailboxesError = ref<string | null>(null);
const showMailboxDialog = ref(false);
const mailboxSaving = ref(false);
const mailboxDraft = ref({ address: "", name: "", isDefault: false });
const selectedMailbox = ref<WorkspaceMailbox | null>(null);
const mailboxAliases = ref<WorkspaceMailboxAlias[]>([]);
const mailboxForwarding = ref<WorkspaceMailboxForwardingRule[]>([]);
const mailboxQuota = ref<WorkspaceMailboxQuota | null>(null);
const mailboxDetailsLoading = ref(false);
const mailboxDetailsError = ref<string | null>(null);
const aliasSaving = ref(false);
const forwardingSaving = ref(false);
const aliasDraft = ref({ customDomainId: "", localPart: "", name: "" });
const forwardingDraft = ref({ aliasId: "", destination: "" });
const credentials = ref<WorkspaceMailCredential[]>([]);
const credentialsLoading = ref(false);
const credentialsError = ref<string | null>(null);
const showCredentialDialog = ref(false);
const credentialSaving = ref(false);
const credentialDraft = ref({ mailboxId: "", label: "", protocols: ["smtp", "imap"] });
const credentialProtocols = ["smtp", "imap", "pop3"];
const createdCredentialSecret = ref<string | null>(null);
const customDomains = ref<WorkspaceCustomDomain[]>([]);
const customDomainUsage = ref<WorkspaceCustomDomainUsage | null>(null);
const customDomainsLoading = ref(false);
const customDomainsError = ref<string | null>(null);
const customDomainBusy = ref<string | null>(null);
const showCustomDomainDialog = ref(false);
const customDomainSaving = ref(false);
const customDomainDraft = ref("");
const mailHost = ref("");
const showMailClientConfiguration = ref(false);
const mailClientConfigurations = [
  { service: "SMTP", server: "mail.solarpass.one", port: 25, security: "STARTTLS / None" },
  { service: "SMTP", server: "mail.solarpass.one", port: 465, security: "SSL/TLS" },
  { service: "SMTP", server: "mail.solarpass.one", port: 587, security: "STARTTLS" },
  { service: "IMAP", server: "mail.solarpass.one", port: 143, security: "STARTTLS / None" },
  { service: "IMAP", server: "mail.solarpass.one", port: 993, security: "SSL/TLS" },
  { service: "POP3", server: "mail.solarpass.one", port: 110, security: "STARTTLS / None" },
  { service: "POP3", server: "mail.solarpass.one", port: 995, security: "SSL/TLS" },
];
const flywheelApps = ref<FlywheelOwnerApp[]>([]);
const flywheelQuota = ref<FlywheelStorageQuota | null>(null);
const flywheelLoading = ref(false);
const flywheelError = ref<string | null>(null);
const selectedFlywheelApp = ref<FlywheelOwnerApp | null>(null);
const flywheelDetailLoading = ref(false);
const flywheelBlobs = ref<FlywheelOwnerBlob[]>([]);
const flywheelAudit = ref<FlywheelAuditEntry[]>([]);
const flywheelTab = ref<"saves" | "audit">("saves");
const tabs = computed(() => [{ id: "overview" as const, label: t("workspaces.overview") }, { id: "plan" as const, label: t("workspaces.managePlan") }, { id: "members" as const, label: t("workspaces.members") }, { id: "mailboxes" as const, label: t("workspaces.mailboxes") }, { id: "flywheel" as const, label: t("workspaces.flywheel") }]);
const roles = computed(() => [{ value: 25, label: t("workspaces.viewer") }, { value: 50, label: t("realms.roleMember") }, { value: 75, label: t("realms.roleAdmin") }, { value: 100, label: t("realms.roleOwner") }]);
const selectedPlanLabel = computed(() => planLabel({ plan: selectedPlan.value?.plan ?? workspace.value?.plan ?? WorkspacePlan.free } as Workspace));
const workspaceCredentials = computed(() => {
  const mailboxIds = new Set(mailboxes.value.map((mailbox) => mailbox.id));
  return credentials.value.filter((credential) => mailboxIds.has(credential.mailboxId));
});
useSolarSeo({ title: computed(() => workspace.value?.name || t("workspaces.detailTitle")), description: t("workspaces.subtitle") });

async function loadWorkspace() { loading.value = true; loadError.value = null; try { const items = await fetchWorkspaces(); workspace.value = items.find((item) => item.slug === slug.value) || null; if (!workspace.value) throw new Error(t("workspaces.notFound")); await Promise.all([loadPlan(), loadMembers(), loadMailboxes(), loadCustomDomains(), loadMailHost(), loadFlywheel()]); } catch (err) { loadError.value = err instanceof Error ? err.message : t("workspaces.loadError"); } finally { loading.value = false; } }
async function loadPlan() { if (!workspace.value) return; planLoading.value = true; try { selectedPlan.value = await fetchWorkspacePlanStatus(workspace.value.slug); } catch (err) { planError.value = err instanceof Error ? err.message : t("workspaces.planError"); } finally { planLoading.value = false; } }
async function loadMembers() { if (!workspace.value) return; membersLoading.value = true; try { members.value = await fetchWorkspaceMembers(workspace.value.slug); } catch (err) { membersError.value = err instanceof Error ? err.message : t("workspaces.membersError"); } finally { membersLoading.value = false; } }
async function loadMailboxes() { if (!workspace.value) return; mailboxesLoading.value = true; credentialsLoading.value = true; mailboxUsageLoading.value = true; try { [mailboxes.value, credentials.value, mailboxUsage.value, sendUsage.value] = await Promise.all([fetchWorkspaceMailboxes(workspace.value.id), fetchMailCredentials(), fetchWorkspaceMailboxUsage(workspace.value.id), fetchWorkspaceSendUsage(workspace.value.id)]); } catch (err) { mailboxesError.value = err instanceof Error ? err.message : t("workspaces.mailboxesError"); credentialsError.value = err instanceof Error ? err.message : t("workspaces.credentialsError"); mailboxUsageError.value = err instanceof Error ? err.message : t("workspaces.mailboxUsageError"); } finally { mailboxesLoading.value = false; credentialsLoading.value = false; mailboxUsageLoading.value = false; } }
async function loadCustomDomains() { if (!workspace.value) return; customDomainsLoading.value = true; customDomainsError.value = null; try { [customDomains.value, customDomainUsage.value] = await Promise.all([fetchWorkspaceCustomDomains(workspace.value.id), fetchWorkspaceCustomDomainUsage(workspace.value.id)]); } catch (err) { customDomainsError.value = err instanceof Error ? err.message : t("workspaces.customDomainsError"); } finally { customDomainsLoading.value = false; } }
async function loadMailHost() { try { mailHost.value = await fetchMailHost(); } catch { mailHost.value = ""; } }
async function loadFlywheel() { if (!workspace.value) return; flywheelLoading.value = true; try { [flywheelApps.value, flywheelQuota.value] = await Promise.all([fetchFlywheelApps(workspace.value.id), fetchFlywheelStorageQuota(workspace.value.id)]); } catch (err) { flywheelError.value = err instanceof Error ? err.message : t("workspaces.flywheelError"); } finally { flywheelLoading.value = false; } }
async function purchasePlan(plan: number) { if (!workspace.value) return; isSubscribing.value = true; try { const order = await subscribeWorkspacePlan(workspace.value.slug, plan); await navigateTo(`/orders/${order.orderId}`); } catch (err) { planError.value = err instanceof Error ? err.message : t("workspaces.planError"); } finally { isSubscribing.value = false; } }
function memberLabel(member: WorkspaceMember) { return member.account?.nick || member.account?.name || member.accountId; }
function memberAvatarUrl(member: WorkspaceMember) { return getFileUrl(member.account?.profile?.picture?.id); }
function handleAvatarError(event: Event) { const image = event.currentTarget as HTMLImageElement; image.classList.add("hidden"); image.nextElementSibling?.classList.remove("hidden"); }
function memberEmail(member: WorkspaceMember) { return member.account?.contacts?.find((contact) => contact.isPrimary)?.content || member.account?.contacts?.[0]?.content || ""; }
async function searchForAccounts() { if (accountQuery.value.trim().length < 2) { accountResults.value = []; return; } try { accountResults.value = await searchAccounts(accountQuery.value.trim(), 20); } catch { accountResults.value = []; } }
async function inviteSelectedAccount() { if (!workspace.value || !inviteAccount.value) return; memberBusy.value = "invite"; try { await inviteWorkspaceMember(workspace.value.slug, inviteAccount.value.id, inviteRole.value); showInviteDialog.value = false; inviteAccount.value = null; accountQuery.value = ""; accountResults.value = []; await loadMembers(); } catch (err) { memberActionError.value = err instanceof Error ? err.message : t("workspaces.membersError"); } finally { memberBusy.value = null; } }
async function changeRole(member: WorkspaceMember, role: number) { if (!workspace.value || role === member.role) return; memberBusy.value = member.accountId; try { await updateWorkspaceMemberRole(workspace.value.slug, member.accountId, role); await loadMembers(); } catch (err) { membersError.value = err instanceof Error ? err.message : t("workspaces.membersError"); } finally { memberBusy.value = null; } }
async function removeMember(member: WorkspaceMember) { if (!workspace.value || !window.confirm(t("workspaces.removeMemberConfirm"))) return; memberBusy.value = member.accountId; try { await removeWorkspaceMember(workspace.value.slug, member.accountId); await loadMembers(); } catch (err) { membersError.value = err instanceof Error ? err.message : t("workspaces.membersError"); } finally { memberBusy.value = null; } }
async function createMailbox() { if (!workspace.value || !mailboxDraft.value.address || (mailboxUsage.value && mailboxUsage.value.remaining <= 0)) return; mailboxSaving.value = true; try { const mailbox = await createWorkspaceMailbox({ address: fullMailboxAddress(mailboxDraft.value.address), name: mailboxDraft.value.name || undefined, workspaceId: workspace.value.id, isDefault: mailboxDraft.value.isDefault }); mailboxes.value.unshift(mailbox); if (mailboxUsage.value) mailboxUsage.value = { ...mailboxUsage.value, used: mailboxUsage.value.used + 1, remaining: Math.max(0, mailboxUsage.value.remaining - 1) }; showMailboxDialog.value = false; mailboxDraft.value = { address: "", name: "", isDefault: false }; } catch (err) { mailboxesError.value = err instanceof Error ? err.message : t("workspaces.mailboxesError"); } finally { mailboxSaving.value = false; } }
async function openMailboxDetails(mailbox: WorkspaceMailbox) { selectedMailbox.value = mailbox; mailboxDetailsLoading.value = true; mailboxDetailsError.value = null; try { [mailboxAliases.value, mailboxForwarding.value, mailboxQuota.value] = await Promise.all([fetchMailboxAliases(mailbox.id), fetchMailboxForwarding(mailbox.id), fetchMailboxQuota(mailbox.id)]); } catch (err) { mailboxDetailsError.value = err instanceof Error ? err.message : t("workspaces.mailboxDetailsError"); } finally { mailboxDetailsLoading.value = false; } }
async function createAlias() { if (!selectedMailbox.value || !aliasDraft.value.customDomainId || !aliasDraft.value.localPart.trim()) return; aliasSaving.value = true; mailboxDetailsError.value = null; try { const alias = await createMailboxAlias({ mailboxId: selectedMailbox.value.id, customDomainId: aliasDraft.value.customDomainId, localPart: aliasDraft.value.localPart.trim().toLowerCase(), name: aliasDraft.value.name.trim() || undefined }); mailboxAliases.value.unshift(alias); aliasDraft.value = { customDomainId: "", localPart: "", name: "" }; } catch (err) { mailboxDetailsError.value = err instanceof Error ? err.message : t("workspaces.mailboxDetailsError"); } finally { aliasSaving.value = false; } }
async function removeAlias(alias: WorkspaceMailboxAlias) { if (!selectedMailbox.value || !window.confirm(t("workspaces.removeAliasConfirm"))) return; try { await deleteMailboxAlias(selectedMailbox.value.id, alias.id); mailboxAliases.value = mailboxAliases.value.filter((item) => item.id !== alias.id); mailboxForwarding.value = mailboxForwarding.value.filter((item) => item.aliasId !== alias.id); } catch (err) { mailboxDetailsError.value = err instanceof Error ? err.message : t("workspaces.mailboxDetailsError"); } }
async function createForwarding() { if (!selectedMailbox.value || !forwardingDraft.value.aliasId || !forwardingDraft.value.destination.trim()) return; forwardingSaving.value = true; mailboxDetailsError.value = null; try { const rule = await createMailboxForwarding({ mailboxId: selectedMailbox.value.id, aliasId: forwardingDraft.value.aliasId, destination: forwardingDraft.value.destination.trim().toLowerCase() }); mailboxForwarding.value.unshift(rule); forwardingDraft.value = { aliasId: "", destination: "" }; } catch (err) { mailboxDetailsError.value = err instanceof Error ? err.message : t("workspaces.mailboxDetailsError"); } finally { forwardingSaving.value = false; } }
async function removeForwarding(rule: WorkspaceMailboxForwardingRule) { if (!selectedMailbox.value || !window.confirm(t("workspaces.removeForwardingConfirm"))) return; try { await deleteMailboxForwarding(selectedMailbox.value.id, rule.id); mailboxForwarding.value = mailboxForwarding.value.filter((item) => item.id !== rule.id); } catch (err) { mailboxDetailsError.value = err instanceof Error ? err.message : t("workspaces.mailboxDetailsError"); } }
async function createCustomDomain() { if (!workspace.value || !customDomainDraft.value.trim() || (customDomainUsage.value && customDomainUsage.value.remaining <= 0)) return; customDomainSaving.value = true; customDomainsError.value = null; try { const domain = await createWorkspaceCustomDomain({ workspaceId: workspace.value.id, domain: customDomainDraft.value.trim().toLowerCase() }); customDomains.value.unshift(domain); if (customDomainUsage.value) customDomainUsage.value = { ...customDomainUsage.value, used: customDomainUsage.value.used + 1, remaining: Math.max(0, customDomainUsage.value.remaining - 1) }; showCustomDomainDialog.value = false; customDomainDraft.value = ""; } catch (err) { customDomainsError.value = err instanceof Error ? err.message : t("workspaces.customDomainsError"); } finally { customDomainSaving.value = false; } }
async function refreshCustomDomain(domain: WorkspaceCustomDomain) { customDomainBusy.value = domain.id; try { const updated = await refreshWorkspaceCustomDomain(domain.id); const index = customDomains.value.findIndex((item) => item.id === domain.id); if (index >= 0) customDomains.value[index] = updated; } catch (err) { customDomainsError.value = err instanceof Error ? err.message : t("workspaces.customDomainsError"); } finally { customDomainBusy.value = null; } }
async function removeCustomDomain(domain: WorkspaceCustomDomain) { if (!window.confirm(t("workspaces.removeCustomDomainConfirm"))) return; customDomainBusy.value = domain.id; try { await deleteWorkspaceCustomDomain(domain.id); customDomains.value = customDomains.value.filter((item) => item.id !== domain.id); } catch (err) { customDomainsError.value = err instanceof Error ? err.message : t("workspaces.customDomainsError"); } finally { customDomainBusy.value = null; } }
async function createCredential() { if (!credentialDraft.value.mailboxId || !credentialDraft.value.label.trim()) return; credentialSaving.value = true; credentialsError.value = null; try { const created: WorkspaceMailCredentialCreated = await createMailCredential({ mailboxId: credentialDraft.value.mailboxId, label: credentialDraft.value.label.trim(), protocols: credentialDraft.value.protocols }); credentials.value.unshift(created.credential); createdCredentialSecret.value = created.secret; showCredentialDialog.value = false; credentialDraft.value = { mailboxId: "", label: "", protocols: ["smtp", "imap"] }; } catch (err) { credentialsError.value = err instanceof Error ? err.message : t("workspaces.credentialsError"); } finally { credentialSaving.value = false; } }
function fullMailboxAddress(address: string) { const normalized = address.trim().toLowerCase(); return normalized.includes("@") ? normalized : `${normalized}@${mailHost.value || "solarpass.one"}`; }
function customDomainRecords(domain: WorkspaceCustomDomain, group: "dkim" | "mailFrom" | "inbound") { return domain.dnsRecords.filter((record) => group === "dkim" ? record.name.includes("._domainkey.") : group === "mailFrom" ? record.name === domain.mailFromDomain : record.type === "MX" && record.name === domain.domain); }
function formatQuotaBytes(bytes: number) { if (bytes >= 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`; if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`; return `${Math.max(0, Math.round(bytes / 1024))} KB`; }
function mailboxAddress(mailboxId: string) { const mailbox = mailboxes.value.find((item) => item.id === mailboxId); return mailbox ? fullMailboxAddress(mailbox.address) : mailboxId; }
async function revokeCredential(credential: WorkspaceMailCredential) { if (!window.confirm(t("workspaces.revokeCredentialConfirm"))) return; try { await revokeMailCredential(credential.id); credentials.value = credentials.value.filter((item) => item.id !== credential.id); } catch (err) { credentialsError.value = err instanceof Error ? err.message : t("workspaces.credentialsError"); } }
async function openFlywheelApp(app: FlywheelOwnerApp) { if (!workspace.value) return; selectedFlywheelApp.value = app; flywheelTab.value = "saves"; flywheelDetailLoading.value = true; try { const [blobs, audit] = await Promise.all([fetchFlywheelBlobs(workspace.value.id, app.appId), fetchFlywheelAudit(workspace.value.id, app.appId)]); flywheelBlobs.value = blobs; flywheelAudit.value = audit; } catch (err) { flywheelError.value = err instanceof Error ? err.message : t("workspaces.flywheelError"); } finally { flywheelDetailLoading.value = false; } }
async function deleteBlob(blob: FlywheelOwnerBlob) { if (!workspace.value || !selectedFlywheelApp.value || !window.confirm(t("workspaces.deleteSaveConfirm"))) return; try { await deleteFlywheelBlob(workspace.value.id, selectedFlywheelApp.value.appId, blob.blobId); flywheelBlobs.value = flywheelBlobs.value.filter((item) => item.blobId !== blob.blobId); } catch (err) { flywheelError.value = err instanceof Error ? err.message : t("workspaces.flywheelError"); } }
function typeLabel(item: Workspace) { return item.type === WorkspaceType.individual ? t("workspaces.personalType") : t("workspaces.workspaceType"); }
function planLabel(item: Workspace) { return item.plan === WorkspacePlan.enterprise ? t("workspaces.enterprise") : item.plan === WorkspacePlan.pro ? t("workspaces.pro") : t("workspaces.free"); }
function formatBytes(bytes: number) { if (bytes >= 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`; if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`; return `${Math.max(0, Math.round(bytes / 1024))} KB`; }
function formatDate(value: string) { return new Date(value).toLocaleString(); }
await loadWorkspace();
</script>

