.workspace-panel details div.overflow-x-auto { border: 1px solid var(--color-base-300); border-radius: 0.375rem; }
section.space-y-4 > article:nth-child(2) > div:nth-child(2) { display: none; }
section.workspace-panel:has(> h2:first-child):has(> div button) { display: none; }
